import type {CSSProperties} from 'react';
import {RollingLabel} from './rolling-label';

/** A persistent entrance keeps the final paint state while hover rolls separately. */
export function NavbarLabel({text,index}:{text:string;index:number}){
  return <span className="navbar-label" aria-hidden="true" style={{'--label-delay':`${430+index*65}ms`} as CSSProperties}><RollingLabel text={text}/></span>;
}

import type {CSSProperties} from 'react';

/** The button owns one accessible label. These duplicate glyphs are visual only. */
export function RollingLabel({text}:{text:string}){
  return <span className="rolling-label" aria-hidden="true">{[...text].map((char,index)=><span className="roll-char" key={index} style={{'--roll-delay':`${index*12}ms`} as CSSProperties}><span className="roll-glyph">{char===' '?'\u00a0':char}</span><span className="roll-glyph">{char===' '?'\u00a0':char}</span></span>)}</span>;
}

.button{position:relative;display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:12px 20px;border-radius:0;border:1px solid transparent;font:inherit;font-size:14px;line-height:1.25;font-weight:500;letter-spacing:-.025em;overflow:hidden;white-space:nowrap;cursor:pointer}
.rolling-label{display:inline-flex;align-items:baseline;line-height:1.35}
.roll-char{position:relative;display:inline-block;overflow:clip;height:1.35em;white-space:pre}
.roll-glyph{display:block;line-height:1.35}
.roll-glyph:last-child{position:absolute;inset:0;transform:translateY(110%)}
.pixel-button::before{content:"";position:absolute;inset:0;background:#fff;z-index:-1;clip-path:polygon(0 0,calc(100% - 9px) 0,calc(100% - 9px) 9px,100% 9px,100% 100%,9px 100%,9px calc(100% - 9px),0 calc(100% - 9px));}
.pixel-button,.pixel-button:hover,.pixel-button:focus-visible{background:transparent;border:0;color:#000;isolation:isolate}
.pixel-button .rolling-label{position:relative}
.button-corners{position:absolute;inset:0;pointer-events:none;z-index:-1}
.button-corner{position:absolute;display:block;width:10px;height:10px;background:#fff;transform:scale(0);transition:transform .36s cubic-bezier(.22,1,.36,1)}
.button-corner-top{right:0;top:0;transform-origin:0 100%}
.button-corner-bottom{left:0;bottom:0;transform-origin:100% 0}
.pixel-button:is(:hover,:focus-visible,:active) .button-corner{transform:scale(1)}
.pixel-button:focus-visible{outline:2px solid #fff;outline-offset:4px}
.pixel-button:is(:hover,:focus-visible,:active){transform:none}
.nav-link{position:relative;display:inline-flex;align-items:center;justify-content:center;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}
.navbar-label{display:inline-block;white-space:nowrap;text-align:center}
.nav-surface,.mobile-cut-surface{display:block;width:100%;height:100%;fill:currentColor;transform-origin:50% 0;pointer-events:none}
.mobile-cut-surface{transform-origin:100% 0}@media(prefers-reduced-motion:no-preference){[data-nav-phase=waiting] .nav-surface,[data-nav-phase=waiting] .mobile-cut-surface{transform:scaleY(0)}:is([data-nav-phase=labels],[data-nav-phase=complete]) .nav-surface,:is([data-nav-phase=labels],[data-nav-phase=complete]) .mobile-cut-surface{animation:navbar-unfold .78s cubic-bezier(.22,1,.36,1) both}@keyframes navbar-unfold{from{transform:scaleY(0)}to{transform:scaleY(1)}}}
.newsletter-ribbon{display:block;width:100%;height:28px;overflow:hidden;border:0;padding:0;background:transparent;color:inherit;white-space:nowrap;font:inherit}
.marquee{display:flex;width:max-content;font-size:14px;line-height:26px;font-weight:500;letter-spacing:.04em}.marquee-item{display:flex;flex:none;align-items:center;gap:28px;padding-right:28px}.marquee .marquee-logo{width:15px;height:15px;overflow:hidden;flex:none}
@media(prefers-reduced-motion:no-preference){.roll-glyph{transition:transform .36s cubic-bezier(.22,1,.36,1) var(--roll-delay)}.button:focus-visible .roll-glyph:first-child,.nav-link:focus-visible .roll-glyph:first-child{transform:translateY(-110%)}.button:focus-visible .roll-glyph:last-child,.nav-link:focus-visible .roll-glyph:last-child{transform:translateY(0)}[data-nav-phase=waiting] .navbar-label{opacity:0}:is([data-nav-phase=labels],[data-nav-phase=complete]) .navbar-label{animation:navbar-label-in .5s var(--ease-out,cubic-bezier(.16,1,.3,1)) var(--label-delay) both}.marquee{animation:newsletter-stream 14s linear infinite}.newsletter-ribbon:hover .marquee,.newsletter-ribbon:focus-visible .marquee{animation-play-state:paused}@keyframes newsletter-stream{to{transform:translateX(calc(-100% / var(--marquee-copies)))}}@keyframes navbar-label-in{from{opacity:0;transform:translateY(-7px)}to{opacity:1;transform:translateY(0)}}}
@media(prefers-reduced-motion:no-preference) and (hover:hover){.button:hover .roll-glyph:first-child,.nav-link:hover .roll-glyph:first-child{transform:translateY(-110%)}.button:hover .roll-glyph:last-child,.nav-link:hover .roll-glyph:last-child{transform:translateY(0)}}
@media(prefers-reduced-motion:reduce){.button .roll-glyph,.nav-link .roll-glyph{transition:none!important;transform:none!important}.roll-glyph:last-child{display:none}.marquee{animation:none}}
.relative{position:relative}.overflow-hidden{overflow:hidden}.pointer-events-none{pointer-events:none}.absolute{position:absolute}.inset-0{inset:0}.top-0{top:0}.left-0{left:0}.max-w-none{max-width:none}.object-cover{object-fit:cover}.bg-muted{background:var(--muted,#000)}.transition-opacity{transition-property:opacity;transition-timing-function:cubic-bezier(.4,0,.2,1)}.duration-500{transition-duration:.5s}.tilted-grid-band img,.tilted-grid-band canvas{display:block}
.pixel-button.button-secondary {
  --corner-cut: 9px;
  --button-shape: polygon(
    0 0, calc(100% - var(--corner-cut)) 0,
    calc(100% - var(--corner-cut)) var(--corner-cut), 100% var(--corner-cut),
    100% 100%, var(--corner-cut) 100%,
    var(--corner-cut) calc(100% - var(--corner-cut)), 0 calc(100% - var(--corner-cut))
  );
  color: #fff;
}

.pixel-button.button-secondary::before,
.pixel-button.button-secondary::after {
  clip-path: var(--button-shape);
  transition: clip-path .36s cubic-bezier(.22,1,.36,1);
}

.pixel-button.button-secondary::after {
  content: "";
  position: absolute;
  inset: 1px;
  z-index: -1;
  background: #000;
}

.pixel-button.button-secondary:is(:hover,:focus-visible,:active) {
  --corner-cut: 0px;
}
